  [("entorno", "lugar donde haces la actividad, como el patio, la plaza o la ciclovía"), ("medida de seguridad", "acción para evitar un accidente, como usar casco"), ("ciclovía", "vía destinada a las bicicletas"), ("supervisión", "presencia de una persona adulta que cuida mientras practicas"), ("riesgo", "posibilidad de que ocurra un daño")],
  [("Elegir la medida", "Vas a andar en bicicleta por la ciclovía. ¿Qué elemento de seguridad indispensable debes llevar puesto?", ["La bicicleta puede causar caídas.", "El casco protege la cabeza.", "Debes llevar casco."], "El casco"),
   ("Cambiar de plan", "Llueve y el patio está resbaloso. ¿Qué haces con tu plan de correr?", ["El piso mojado aumenta el riesgo de caídas.", "Buscas un lugar techado y seco.", "Cambias el lugar o la actividad."], "Cambio a un lugar techado y seco")],
  [("Salir sin avisar adónde vas.", "Si hay un problema, nadie sabe dónde estás.", "Avisa adónde vas y a qué hora vuelves."), ("Usar el casco solo cuando vas rápido.", "Las caídas ocurren también a baja velocidad.", "Úsalo siempre.")],
